export const GameState = Object.freeze({
  Start: 0,
  Gaming: 1,
  Won: 2,
  Dead: 3,
});

export const CellState = Object.freeze({
  Covered: 0,
  Uncovered: 1,
  Flagged: 2,
});

function createCell() {
  return {
    state: CellState.Covered,
    isBomb: false,
    bombNum: 0,
  };
}

function getNeighborCoordinates(row, col, rowCount, colCount) {
  const coordinates = [];

  for (let nextRow = Math.max(0, row - 1); nextRow <= Math.min(row + 1, rowCount - 1); nextRow++) {
    for (
      let nextCol = Math.max(0, col - 1);
      nextCol <= Math.min(col + 1, colCount - 1);
      nextCol++
    ) {
      if (nextRow === row && nextCol === col) {
        continue;
      }

      coordinates.push([nextRow, nextCol]);
    }
  }

  return coordinates;
}

export class MinesweeperBoard {
  constructor(row, col, bombPercentage, options = {}) {
    this.row = row;
    this.col = col;
    this.bombCnt = Math.floor(row * col * bombPercentage);
    this.flagCnt = this.bombCnt;
    this.foundCnt = 0;
    this.state = GameState.Start;
    this.randomFn = options.randomFn || Math.random;
    this.cells = Array.from({ length: row }, () =>
      Array.from({ length: col }, () => createCell()),
    );

    this.placeBombs(options.bombCoordinates);
    this.fillBombCounts();
  }

  isInBounds(row, col) {
    return row >= 0 && row < this.row && col >= 0 && col < this.col;
  }

  getCell(row, col) {
    return this.cells[row][col];
  }

  getBombCells() {
    const bombs = [];

    for (let row = 0; row < this.row; row++) {
      for (let col = 0; col < this.col; col++) {
        if (this.cells[row][col].isBomb) {
          bombs.push({ row, col });
        }
      }
    }

    return bombs;
  }

  placeBombs(bombCoordinates) {
    if (bombCoordinates?.length) {
      bombCoordinates.forEach(([row, col]) => {
        if (!this.isInBounds(row, col)) {
          throw new Error(`Bomb coordinate out of bounds: ${row},${col}`);
        }

        this.cells[row][col].isBomb = true;
      });

      this.bombCnt = bombCoordinates.length;
      this.flagCnt = this.bombCnt;
      return;
    }

    let bombsPlaced = 0;

    while (bombsPlaced !== this.bombCnt) {
      const row = Math.floor(this.randomFn() * this.row);
      const col = Math.floor(this.randomFn() * this.col);
      const cell = this.cells[row][col];

      if (cell.isBomb) {
        continue;
      }

      cell.isBomb = true;
      bombsPlaced++;
    }
  }

  fillBombCounts() {
    for (let row = 0; row < this.row; row++) {
      for (let col = 0; col < this.col; col++) {
        const cell = this.cells[row][col];

        if (cell.isBomb) {
          continue;
        }

        cell.bombNum = getNeighborCoordinates(row, col, this.row, this.col).filter(
          ([neighborRow, neighborCol]) => this.cells[neighborRow][neighborCol].isBomb,
        ).length;
      }
    }
  }

  toggleFlag(row, col) {
    const cell = this.getCell(row, col);

    if (this.state === GameState.Dead || this.state === GameState.Won) {
      return { changed: false, reason: "game-over", state: cell.state };
    }

    if (cell.state === CellState.Uncovered) {
      return { changed: false, reason: "uncovered", state: cell.state };
    }

    if (cell.state === CellState.Flagged) {
      cell.state = CellState.Covered;
      this.flagCnt++;
      return { changed: true, reason: "unflagged", state: cell.state };
    }

    if (this.flagCnt === 0) {
      return { changed: false, reason: "no-flags-remaining", state: cell.state };
    }

    cell.state = CellState.Flagged;
    this.flagCnt--;
    if (this.state === GameState.Start) {
      this.state = GameState.Gaming;
    }

    return { changed: true, reason: "flagged", state: cell.state };
  }

  reveal(row, col) {
    const cell = this.getCell(row, col);

    if (this.state === GameState.Dead || this.state === GameState.Won) {
      return { changed: false, reason: "game-over", revealed: [] };
    }

    if (cell.state === CellState.Flagged) {
      return { changed: false, reason: "flagged", revealed: [] };
    }

    if (cell.state === CellState.Uncovered) {
      return { changed: false, reason: "already-uncovered", revealed: [] };
    }

    if (cell.isBomb) {
      cell.state = CellState.Uncovered;
      this.state = GameState.Dead;

      return {
        changed: true,
        explodedCell: { row, col },
        reason: "bomb",
        revealed: [{ row, col, bombNum: cell.bombNum, isBomb: true }],
      };
    }

    const revealed = [];
    const queue = [[row, col]];
    const visited = new Set();

    while (queue.length > 0) {
      const [currentRow, currentCol] = queue.shift();
      const key = `${currentRow}-${currentCol}`;

      if (visited.has(key) || !this.isInBounds(currentRow, currentCol)) {
        continue;
      }

      visited.add(key);

      const currentCell = this.getCell(currentRow, currentCol);

      if (
        currentCell.state === CellState.Uncovered ||
        currentCell.state === CellState.Flagged ||
        currentCell.isBomb
      ) {
        continue;
      }

      currentCell.state = CellState.Uncovered;
      this.foundCnt++;
      revealed.push({
        row: currentRow,
        col: currentCol,
        bombNum: currentCell.bombNum,
        isBomb: false,
      });

      if (currentCell.bombNum !== 0) {
        continue;
      }

      queue.push(
        ...getNeighborCoordinates(currentRow, currentCol, this.row, this.col),
      );
    }

    if (revealed.length > 0 && this.state === GameState.Start) {
      this.state = GameState.Gaming;
    }

    if (this.foundCnt === this.row * this.col - this.bombCnt) {
      this.state = GameState.Won;
    }

    return {
      changed: revealed.length > 0,
      reason: "safe",
      revealed,
      won: this.state === GameState.Won,
    };
  }
}
